        if start in processed:
            continue
        path = []
        on_path = set()
        cur = start
        while True:
            if cur not in A or F[cur] == cur:
                break
            if cur in processed:
                break
            if cur in on_path:
                cycles += 1
                break
            on_path.add(cur)
            path.append(cur)
            cur = F[cur]
        for p in path:
            processed.add(p)

    print(edges + cycles)

